style.css:
@-moz-document domain("youtube.com") {
:root {
    --cream: #eee4d2;
    --beige: #dfcfb5;
    --mocha: #806447;
    --caramel: #a78b67;
    --champagne: #fff8e9;
    --glass: rgba(244,232,211,.72);
}

/* MAIN BACKGROUND */
html, body, ytd-app {
    background: #e9deca !important;
}

/* PAGE BACKGROUND */
#content,
#page-manager,
ytd-browse,
ytd-watch-flexy {
    background:
        radial-gradient(ellipse at 15% 10%,
        #fffaf0 0%, transparent 45%),
        radial-gradient(ellipse at 85% 90%,
        #cdbb9e 0%, transparent 50%),
        linear-gradient(135deg,
        #eee4d2, #d8c7ad) !important;
}

/* TOP NAVIGATION GLASS */
#masthead-container,
ytd-masthead {
    background: rgba(246,237,220,.82) !important;
    backdrop-filter: blur(25px) saturate(160%);
    border-bottom: 1px solid white !important;
}

/* SIDEBAR */
#guide,
ytd-mini-guide-renderer {
    background: rgba(224,210,188,.83) !important;
    backdrop-filter: blur(25px);
    border-right: 1px solid white !important;
}

/* VIDEO CARDS */
ytd-rich-item-renderer,
ytd-video-renderer,
ytd-compact-video-renderer {
    background: var(--glass) !important;
    border: 1px solid rgba(255,255,255,.85) !important;
    border-radius: 19px !important;
    padding: 9px !important;
    box-shadow:
        inset 0 2px 5px rgba(255,255,255,.9),
        inset 0 -3px 8px rgba(150,120,85,.12),
        0 7px 20px rgba(100,75,45,.12) !important;
    backdrop-filter: blur(18px);
    transition: .25s ease !important;
}

ytd-rich-item-renderer:hover,
ytd-video-renderer:hover {
    transform: translateY(-3px);
    background: rgba(255,249,237,.9) !important;
}

/* THUMBNAILS */
ytd-thumbnail,
#thumbnail {
    border-radius: 15px !important;
    overflow: hidden !important;
}

/* SEARCH BAR */
#search-form,
#container.ytd-searchbox {
    background: rgba(255,249,237,.8) !important;
    border: 1px solid white !important;
    border-radius: 30px !important;
    box-shadow:
        inset 0 2px 5px white,
        0 4px 12px rgba(120,90,55,.13) !important;
}

/* BUTTONS */
yt-button-shape button,
ytd-button-renderer button {
    background: linear-gradient(
        145deg, #fff9ed, #dfceb3
    ) !important;
    color: var(--mocha) !important;
    border: 1px solid white !important;
    border-radius: 24px !important;
    box-shadow:
        inset 0 2px 4px white,
        0 3px 8px rgba(100,75,45,.12) !important;
}

/* ALL GENERAL TEXT */
#video-title,
h1, h2, h3,
yt-formatted-string {
    color: #806447 !important;
}

/* VIDEO TITLE */
ytd-watch-metadata h1,
#above-the-fold h1 {
    color: #72583e !important;
}

/* VIDEO CAPTIONS — DARK BEIGE */
.ytp-caption-segment {
    color: #b59a76 !important;
    font-weight: 600 !important;
    -webkit-text-stroke: .35px #6e573d !important;
    text-shadow:
        0 1px 2px rgba(54,38,22,.9),
        0 2px 6px rgba(54,38,22,.45) !important;
}

/* CAPTION BACKGROUND */
.ytp-caption-window-container {
    background: transparent !important;
}

/* VIDEO PLAYER CONTROLS */
.ytp-chrome-bottom,
.ytp-chrome-top {
    color: #b49a78 !important;
}

/* VIDEO TIMESTAMPS */
.ytp-time-current,
.ytp-time-duration {
    color: #c1a782 !important;
}

/* PLAYER BUTTONS */
.ytp-button {
    color: #ad906b !important;
}

.ytp-button:hover {
    color: #806447 !important;
    filter: drop-shadow(
        0 1px 3px rgba(120,90,55,.3)
    );
}

/* SCROLLBAR */
::-webkit-scrollbar {
    width: 9px;
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(
        #fff6e5, #cbb697
    );
    border-radius: 20px;
    border: 2px solid #e9dfcc;
}

/* TEXT SELECTION */
::selection {
    background: #bda27e;
    color: white;
}
}
